  Eidis:H('Eidis',X('Eidis ir vārda Eduards forma; no tā cēlies arī uzvārds Eidiņš.','Eidis — форма имени Эдуард (Eduards); от него происходит и фамилия Eidiņš.','Eidis is a form of Eduards and has given the surname Eidiņš.','Eidis – vardo Eduards forma; iš jo kilo ir pavardė Eidiņš.','Eidis on nime Eduards kuju; sellest on tulnud ka perekonnanimi Eidiņš.'),rec('krustp',1922,1932)),
  Elfrīde:H('Elfrīde',X('Elfrīde un Elfrīda darinātas no senaugšvācu alp — «lauma, elfs» — un fridu — «patvērums, miers».','Elfrīde и Elfrīda образованы от древневерхненемецких alp — «эльф» — и fridu — «убежище, мир».','Elfrīde and Elfrīda are formed from Old High German alp, “elf”, and fridu, “refuge, peace”.','Elfrīde ir Elfrīda sudarytos iš senosios aukštaičių vokiečių alp – „elfas, laumė“ – ir fridu – „prieglobstis, taika“.','Elfrīde ja Elfrīda on moodustatud vanaülemsaksa sõnadest alp, „päkapikk, haldjas”, ja fridu, „varjupaik, rahu”.'),rec('riga',1885,1892)),
  Elfrīda:H('Elfrīda',X('Elfrīda un Elfrīde darinātas no senaugšvācu alp — «lauma, elfs» — un fridu — «patvērums, miers».','Elfrīda и Elfrīde образованы от древневерхненемецких alp — «эльф» — и fridu — «убежище, мир».','Elfrīda and Elfrīde are formed from Old High German alp, “elf”, and fridu, “refuge, peace”.','Elfrīda ir Elfrīde sudarytos iš senosios aukštaičių vokiečių alp – „elfas, laumė“ – ir fridu – „prieglobstis, taika“.','Elfrīda ja Elfrīde on moodustatud vanaülemsaksa sõnadest alp, „päkapikk, haldjas”, ja fridu, „varjupaik, rahu”.'),rec('riga',1885,1892)),
  Eltons:H('Eltons',X('Eltons cēlies no angļu vietvārda Elton: senangļu eald — «vecs» — un tūn — «muiža, ciems».','Eltons восходит к английскому топониму Elton: древнеанглийские eald — «старый» — и tūn — «усадьба, селение».','Eltons comes from the English place name Elton, from Old English eald, “old”, and tūn, “estate, village”.','Eltons kilęs iš anglų vietovardžio Elton: senosios anglų eald – „senas“ – ir tūn – „dvaras, kaimas“.','Eltons pärineb inglise kohanimest Elton: vanainglise eald, „vana”, ja tūn, „mõis, küla”.'),rec('liep',1979)),
  Emiljana:H('Emiljana',T.fem('Emiljana','Emiljans'),rec('indra',1749,1932)),
  Enrija:H('Enrija',T.fem('Enrija','Henrijs'),rec('jek',1922)),
