  Ervīns:H('Ervīns',X('Ervīns darināts no senaugšvācu era — «gods» — vai heri — «karaspēks» — un wini — «draugs». Mīļvārdi — Evučs, Edzis, Irvings, Irvins.','Ervīns образовано от древневерхненемецких era — «честь» — или heri — «войско» — и wini — «друг». Ласкательные формы — Evučs, Edzis, Irvings, Irvins.','Ervīns is formed from Old High German era, “honour”, or heri, “army”, and wini, “friend”. Its pet forms include Evučs, Edzis, Irvings and Irvins.','Ervīns sudarytas iš senosios aukštaičių vokiečių era – „garbė“ – arba heri – „kariuomenė“ – ir wini – „draugas“. Maloniosios formos – Evučs, Edzis, Irvings, Irvins.','Ervīns on moodustatud vanaülemsaksa sõnadest era, „au”, või heri, „sõjavägi”, ja wini, „sõber”. Hellitusvormid on Evučs, Edzis, Irvings, Irvins.'),rec('salaspils',1893)),
  Feja:H('Feja',X('Feja ir latviešu vārds feja — «pasaku brīnumdare»; to saista arī ar grieķu thea — «dieviete».','Feja — латышское слово feja — «фея, сказочная волшебница»; его связывают и с греческим thea — «богиня».','Feja is the Latvian word feja, “fairy”, and is also linked with Greek thea, “goddess”.','Feja – latvių žodis feja – „fėja, pasakų burtininkė“; jis siejamas ir su graikų thea – „deivė“.','Feja on läti sõna feja, „haldjas, muinasjutu võluja”; seda seostatakse ka kreeka sõnaga thea, „jumalanna”.'),rec('zlekas','c20q2')),
  Frida:H('Frida',X('Frida ir vārdu Friderika un Elfrīda saīsinājums; vāciski to saista arī ar «miers», skandināviski — ar «prieks».','Frida — сокращение имён Фридерика и Эльфрида; по-немецки его связывают и со словом «мир», по-скандинавски — с «радость».','Frida is a short form of Friderika and Elfrīda; in German it is also linked with “peace”, in Scandinavian with “joy”.','Frida – vardų Friderika ir Elfrīda trumpinys; vokiškai jis siejamas ir su „taika“, skandinaviškai – su „džiaugsmas“.','Frida on nimede Friderika ja Elfrīda lühivorm; saksa keeles seostatakse seda ka sõnaga „rahu”, skandinaavia keeltes „rõõm”.'),rec('smiltene',1878,1889)),
  Gaidis:H('Gaidis',T.masc('Gaidis','Gaida'),rec('riga',1922,1889)),
  Gintis:H('Gintis',X('Gints un Gintis ir lietuviešu vārdu ar Gint- saīsinājums; Gints ir arī varonis Henrika Ibsena drāmā «Pērs Gints». Mīļvārds — Gintišs.','Gints и Gintis — сокращение литовских имён на Gint-; Гюнт — и герой драмы Генрика Ибсена «Пер Гюнт». Ласкательная форма — Gintišs.','Gints and Gintis are short forms of Lithuanian names beginning with Gint-; Gynt is also the hero of Henrik Ibsen’s play Peer Gynt. The pet form is Gintišs.','Gints ir Gintis – lietuviškų vardų su Gint- trumpiniai; Gintas – ir Henriko Ibseno dramos „Peras Giuntas“ herojus. Maloninė forma – Gintišs.','Gints ja Gintis on leedu Gint-algusega nimede lühivormid; Gynt on ka Henrik Ibseni draama „Peer Gynt” kangelane. Hellitusvorm on Gintišs.'),rec('riga',1922,1910)),
  Glafīra:H('Glafīra',T.greek('Glafīra','glaphyra',['gracioza, slaida','изящная, стройная','graceful, slender','grakšti, liekna','graatsiline, sale']),rec('vidz','c19q3',1899)),
